/usr/bin/bash -lc "set -e
{
  printf '%s\\n' '*** Begin Patch'
  jq -r '.rules[] | select(.rule==\"@performance/hp-arkui-remove-redundant-state-var\" or .rule==\"@performance/hp-arkui-remove-unchanged-state-var\") | .files[] | .relative_path as "'$p | .locations[] | [$p,.line] | @tsv'"' .exp_agent/round_01/plan.json | sort -k1,1 -k2,2n | awk -F '\\t' '
    {
      path="'$1; line=$2;
      if (path != current) {
        if (current != "") printf "'"\\n\";
        printf \"*** Update File: %s\\n\", path;
        current=path;
      }
      cmd=\"sed -n \" line \"p \\\"\" path \"\\\"\";
      cmd | getline old;
      close(cmd);
      new=old;
      sub(/@State[[:space:]]+/, \"\", new);
      printf \"@@ -%s,1 +%s,1 @@\\n-%s\\n+%s\\n\", line, line, old, new;
    }
  '
  printf '%s\\n' '*** End Patch'
} | apply_patch
printf 'state decorator repairs applied\\n'"

