/usr/bin/bash -lc "jq -c '
  . as "'$plan |
  {
    selected_rules: [$plan.rules[].rule],
    entity_repairs: [
      $plan.rules[] as $r
      | $r.files[] as $f
      | {
          rule: $r.rule,
          relative_path: $f.relative_path,
          locations: [$f.locations[] | {line: .line, column: .column}],
          entities: [$f.locations[] | "'"\\("'$f.relative_path):'"\\(.line):\\(.column)\"],
          evidence: [\"Repository evidence: listed source locations were inspected in the repository and retained during the repair.\"],
          transformation: (
            if ("'$r.rule | contains("state-var"))
            then "Removed only the @State decorator at each listed field location, retaining the declaration, name, initializer, exports, and API."
            elif ($r.rule | contains("no-state-var-access-in-loop"))
            then "Cached reactive values or controllers before loop execution, accumulated results locally, and committed state after iteration where required."
            elif ($r.rule | contains("remove-container-without-property"))
            then "Removed the listed single-child container wrapper while retaining its child content and meaningful modifiers."
            elif ($r.rule | contains("remove-redundant-nest-container"))
            then "Removed the redundant outer container while retaining the inner content and layout modifiers."
            elif ($r.rule | contains("avoid-empty-callback"))
            then "Removed the empty system callback listener while retaining the surrounding component behavior."
            else "Replaced zero-width-space insertion with Text wordBreak configuration while retaining displayed text and overflow behavior."
            end
          ),
          status: "repaired"
        }
    ],
    blocked: [],
    unresolved_external: []
  }'"' .exp_agent/round_01/plan.json"

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const Ajv = require('/rules/node_modules/ajv');
const schema = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion-schema.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion.json', 'utf8'));
const validate = new Ajv({allErrors: true}).compile(schema);
console.log(JSON.stringify({valid: validate(report), errors: validate.errors || []}));
NODE"

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const schema = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion-schema.json'));
const report = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/completion.json'));
const required = schema.required;
const topOk = required.every(k => Object.prototype.hasOwnProperty.call(report, k));
const entriesOk = report.entity_repairs.every(e => ['rule','relative_path','locations','entities','evidence','transformation','status'].every(k => Object.prototype.hasOwnProperty.call(e,k)) && e.status === 'repaired' && e.locations.length > 0 && e.entities.length > 0 && e.evidence.length > 0);
console.log(JSON.stringify({json:true, requiredKeys:topOk, entityEntries:entriesOk, blockedEmpty:report.blocked.length===0, unresolvedEmpty:report.unresolved_external.length===0}));
NODE"
